import{_ as a,o as t,c as i,a4 as n}from"./chunks/framework.BBs01uty.js";const k=JSON.parse('{"title":"Skill 文件化的提示词工程","description":"","frontmatter":{"title":"Skill 文件化的提示词工程","date":"2026-08-20T00:00:00.000Z"},"headers":[],"relativePath":"ai-agent/prompt-engineering/skills.md","filePath":"ai-agent/prompt-engineering/skills.md"}'),l={name:"ai-agent/prompt-engineering/skills.md"};function e(o,s,d,p,r,h){return t(),i("div",null,[...s[0]||(s[0]=[n(`<h1 id="skill-文件化的提示词工程" tabindex="-1">Skill：文件化的提示词工程 <a class="header-anchor" href="#skill-文件化的提示词工程" aria-label="Permalink to &quot;Skill：文件化的提示词工程&quot;">​</a></h1><blockquote><p>本质一句话：<strong>Skill 是一份被&quot;按需注入到模型上下文里的 Markdown 提示词文件&quot;</strong>，它不执行任何特殊代码，智能全部来自 LLM 遵循这份文本指令。</p></blockquote><p>它与本栏目 <a href="./basics.html">基础技巧</a> 里讲的提示词工程是同一血脉——Skill 就是提示词工程的&quot;工业化版本&quot;：把一段专家指令沉淀成可发现、可复用、可治理的文件。</p><h2 id="为什么需要-skill" tabindex="-1">为什么需要 Skill <a class="header-anchor" href="#为什么需要-skill" aria-label="Permalink to &quot;为什么需要 Skill&quot;">​</a></h2><p>裸提示词工程每次都要在对话框里手敲一长段指令，有几个痛点：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>裸提示词工程的痛点：</span></span>
<span class="line"><span>- 不可复用：同一个专家指令每次重抄</span></span>
<span class="line"><span>- 不可共享：团队成员各写各的，质量参差</span></span>
<span class="line"><span>- 不可发现：模型不知道&quot;有这份能力&quot;可用</span></span>
<span class="line"><span>- 不好约束：无法限制它能使用什么工具</span></span></code></pre></div><p>Skill 把提示词工程<strong>文件化、可复用、可治理</strong>：</p><table tabindex="0"><thead><tr><th>维度</th><th>裸提示词</th><th>Skill</th></tr></thead><tbody><tr><td>载体</td><td>聊天框临时文字</td><td><code>SKILL.md</code> 文件，可版本管理、可共享</td></tr><tr><td>发现</td><td>手动粘贴</td><td>靠 <code>description</code> 让模型自动匹配触发</td></tr><tr><td>治理</td><td>无</td><td><code>allowed-tools</code> 工具白名单、<code>context: fork</code> 隔离</td></tr><tr><td>复用</td><td>每次重抄</td><td>一次写好，全项目/全用户复用</td></tr></tbody></table><h2 id="它怎么实现的-两段式加载" tabindex="-1">它怎么实现的（两段式加载） <a class="header-anchor" href="#它怎么实现的-两段式加载" aria-label="Permalink to &quot;它怎么实现的（两段式加载）&quot;">​</a></h2><p>核心是一个**懒加载（lazy loading）**设计，避免把所有 Skill 正文都塞进上下文撑爆 token。</p><h3 id="阶段-1-启动注册-只加载元数据" tabindex="-1">阶段 1：启动注册（只加载元数据） <a class="header-anchor" href="#阶段-1-启动注册-只加载元数据" aria-label="Permalink to &quot;阶段 1：启动注册（只加载元数据）&quot;">​</a></h3><p>启动时扫描固定目录，对每个 <code>SKILL.md</code> 只解析 YAML frontmatter（<code>name</code> / <code>description</code> / <code>allowed-tools</code>），并估算正文 token 数。这些轻量元数据被放进<strong>技能注册表</strong>，以&quot;可用技能清单&quot;形式呈现给模型——模型因此知道&quot;有这些技能、各自干嘛用&quot;，但<strong>完整正文还没进上下文</strong>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.codebuddy/skills/      # 项目级（优先级高）</span></span>
<span class="line"><span>~/.codebuddy/skills/    # 用户级</span></span>
<span class="line"><span>插件来源                # Plugin skills</span></span></code></pre></div><h3 id="阶段-2-触发时注入-按需拉正文" tabindex="-1">阶段 2：触发时注入（按需拉正文） <a class="header-anchor" href="#阶段-2-触发时注入-按需拉正文" aria-label="Permalink to &quot;阶段 2：触发时注入（按需拉正文）&quot;">​</a></h3><p>当模型根据用户任务比对各 Skill 的 <code>description</code> 认为&quot;该用这个了&quot;（自动），或你手动 <code>/skill-name</code> 时：</p><ol><li>系统按名字从磁盘读取完整 <code>SKILL.md</code> 正文；</li><li>做模板渲染：替换 <code>$ARGUMENTS</code>、<code>\${ENV}</code>、执行 <code>!</code>command\`\`、注入 <code>@file</code>；</li><li>把渲染后的内容注入对话上下文，模型随后照着这份指令干活。</li></ol><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sequenceDiagram</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant U as 用户</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant M as 模型</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant R as 技能注册表</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant F as SKILL.md 文件</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over M,R: 启动后：只注册 name+description（极便宜）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    M-&gt;&gt;R: 看到任务，比对 description</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    M-&gt;&gt;F: 决定调用某 Skill（按需加载正文）</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    F--&gt;&gt;M: 渲染后的指令注入上下文</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    M-&gt;&gt;U: 按 Skill 指令完成回答</span></span></code></pre></div><p><strong>为什么要这样分两段</strong>：若几十个 Skill 正文全常驻上下文，token 成本爆炸；只留 name+description 极便宜。工具里的&quot;预估 token 数量&quot;正是阶段 1 算出来的——平时只占元数据那点开销，触发时才把整本&quot;说明书&quot;翻开放进上下文。</p><h2 id="skill-md-长什么样" tabindex="-1">SKILL.md 长什么样 <a class="header-anchor" href="#skill-md-长什么样" aria-label="Permalink to &quot;SKILL.md 长什么样&quot;">​</a></h2><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">pdf</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">PDF 文档处理和转换专家</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">allowed-tools</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Read, Write, Bash, WebFetch</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">---</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># PDF 处理专家</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">你是一个专业的 PDF 文档处理专家。</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 工作流程</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">1.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 检查 PDF 文件是否存在并可访问</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">2.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 使用 pdftotext 或 pdfinfo 获取基本信息</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">3.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 根据任务类型选择合适的处理工具</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">4.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 验证输出结果的完整性</span></span></code></pre></div><p>支持的写法（与斜杠命令一致）：</p><ul><li><strong>变量占位符</strong>：<code>\${CODEBUDDY_SKILL_DIR}</code>、<code>\${MY_ENV_VAR:-默认值}</code>（也兼容 Claude Code 的 <code>\${CLAUDE_SKILL_DIR}</code> 别名）</li><li><strong>内联 Shell</strong>：<code>!</code>command\`\` 会把 stdout 替换进正文</li><li><strong>文件引用</strong>：<code>@src/utils/helpers.js</code> 把文件内容注入上下文</li></ul><h2 id="谁提出的-有国际标准吗" tabindex="-1">谁提出的？有国际标准吗 <a class="header-anchor" href="#谁提出的-有国际标准吗" aria-label="Permalink to &quot;谁提出的？有国际标准吗&quot;">​</a></h2><ul><li><strong>提出方</strong>：Anthropic（Claude），于 <strong>2025 年 10 月</strong> 随 Claude（Claude.ai / Claude Code / Agent SDK）正式推出 &quot;Agent Skills&quot;。</li><li><strong>国际标准</strong>：<strong>没有</strong> ISO / IETF 之类的官方标准。它属于<strong>事实标准 / 行业惯例</strong>——Claude Code 的 <code>SKILL.md</code> 格式是事实上的参考实现，其他工具（如 CodeBuddy）主动对齐它（保留 <code>\${CLAUDE_*}</code> 别名就是证据）。</li><li><strong>与 MCP 区分</strong>：常被比较的 <strong>MCP（Model Context Protocol）</strong> 是 Anthropic 推出的<strong>真·开放协议</strong>（有规范、跨厂商），用于定义 Agent 连接外部工具；而 Skill 只是&quot;知识/流程的提示词包&quot;，目前没有走标准化协议路线。</li></ul><h2 id="skill-vs-slash-command" tabindex="-1">Skill vs Slash Command <a class="header-anchor" href="#skill-vs-slash-command" aria-label="Permalink to &quot;Skill vs Slash Command&quot;">​</a></h2><table tabindex="0"><thead><tr><th>特性</th><th>Skills</th><th>Slash Commands</th></tr></thead><tbody><tr><td>触发</td><td>模型自动识别调用</td><td>用户手动 <code>/xxx</code></td></tr><tr><td>场景</td><td>专业领域任务</td><td>快捷操作 / 工作流</td></tr><tr><td>权限</td><td>支持工具白名单</td><td>无特殊权限控制</td></tr></tbody></table><p>简单说：<strong>Slash Command 是用户主动调用的快捷方式；Skill 是 AI 根据任务需求自动选择的专业能力。</strong></p><h2 id="skill-vs-mcp-关键对比" tabindex="-1">Skill vs MCP（关键对比） <a class="header-anchor" href="#skill-vs-mcp-关键对比" aria-label="Permalink to &quot;Skill vs MCP（关键对比）&quot;">​</a></h2><p>在 <a href="/knowledge/ai-agent/function-calling.html">Function Calling</a> 一文里讲过：MCP 是&quot;工具分发协议&quot;，让模型能调用外部服务的真实代码。Skill 和它是完全不同的两层：</p><table tabindex="0"><thead><tr><th>维度</th><th>Skill</th><th>MCP</th></tr></thead><tbody><tr><td>实质</td><td><strong>提示词包</strong>（context 注入）</td><td><strong>通信协议</strong>（tool 调用）</td></tr><tr><td>跑不跑代码</td><td>不跑，只把 Markdown 指令塞进上下文</td><td>Server 跑<strong>真实程序 / 外部 API</strong></td></tr><tr><td>扩展的是</td><td>知识、流程、话术</td><td>真实世界操作能力（连库、联网、写盘）</td></tr><tr><td>标准化</td><td>事实惯例（Claude 引领）</td><td>开放协议（有规范、跨厂商）</td></tr><tr><td>触发</td><td>模型按 description 自动选 / 手动 <code>/</code></td><td>模型决定调用某个 Tool</td></tr></tbody></table><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    U[用户任务] --&gt; M[模型]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    M --&gt;|自动匹配 description| S[Skill: 注入提示词&lt;br/&gt;模型照做]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    M --&gt;|Function Calling| T[MCP Tool: 调外部服务&lt;br/&gt;服务跑真实代码]</span></span></code></pre></div><p>二者互补不冲突：</p><ul><li><strong>MCP 给模型&quot;手&quot;</strong>（能真实操作外部系统）；</li><li><strong>Skill 给模型&quot;脑子/经验&quot;</strong>（知道在这种场景下该怎么用那双手）。</li></ul><p>在 CodeBuddy 里，Skill 的 <code>allowed-tools</code> 可以开放 MCP 提供的工具——<strong>Skill 负责&quot;何时、怎么做&quot;，MCP 负责&quot;真去执行&quot;</strong>。</p><h2 id="与-function-calling-的关系" tabindex="-1">与 Function Calling 的关系 <a class="header-anchor" href="#与-function-calling-的关系" aria-label="Permalink to &quot;与 Function Calling 的关系&quot;">​</a></h2><p>Skill 本身<strong>不调用工具、不执行代码</strong>。它只是把一段专家指令注入上下文，模型读完后，仍是通过自身的 <strong>Function Calling 能力</strong>去调用工具（无论是 app 内写死的函数，还是 MCP Server 暴露的 Tool）。</p><p>所以可以这样串起来（呼应 <a href="/knowledge/ai-agent/function-calling.html">Function Calling</a> 一文）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>裸 Function Calling：开发者手写工具 + 注册 schema，模型调用</span></span>
<span class="line"><span>+ MCP：工具来自外部协议化服务，一次实现跨应用复用</span></span>
<span class="line"><span>+ Skill：在&quot;何时、按什么流程&quot;调用工具这件事上，给模型一份可复用的专家说明书</span></span></code></pre></div><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ol><li><strong>清晰的 <code>description</code></strong>：模型靠它匹配触发，写清&quot;能处理什么任务&quot;。</li><li><strong>详细的正文指令</strong>：核心能力、标准流程、可用工具、输出格式都写清楚。</li><li><strong>最小权限</strong>：<code>allowed-tools</code> 只授予必需工具，如 <code>Bash(git:*)</code>, <code>Read</code>。</li><li><strong>按需组织目录</strong>：按领域分子目录（document / data / code），便于团队共享。</li></ol><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>Skill = 把提示词工程沉淀成&quot;可发现、可复用、可治理&quot;的 Markdown 文件。它和 Prompt Engineering 是同一血脉——<strong>如果你已经在练提示词工程，Skill 就是它的&quot;工业化版本&quot;</strong>。它需要配合 Function Calling / MCP 才能真正&quot;动手&quot;，但本身只负责&quot;把专家经验递到模型手上&quot;。</p>`,42)])])}const g=a(l,[["render",e]]);export{k as __pageData,g as default};
